import raw from './report.json';
import type { Report } from '@/lib/engine/report';
import { assetsFor } from '@/components/report/assets';
import { SITE } from '@/lib/site';

/** A real PageGrade report, generated by the engine for the fictional Brightline Digital demo page (see scripts/build-sample.ts). */
export const DEMO_PATH = '/demo/brightline-digital.html';
export const DEMO_URL = `${SITE.url}${DEMO_PATH}`;
export const SAMPLE_REPORT = JSON.parse(JSON.stringify(raw).split('__DEMO_URL__').join(DEMO_URL)) as Report;
export const SAMPLE_ASSETS = assetsFor(SAMPLE_REPORT, (file) => `/sample/${file}`);
